SELECT ?point ?tsid ?name
WHERE {
  ?point a brick:AirTemperatureSensor ;
         brick:hasParentZone ?zone .
  ?zone rdfs:label ?name .
  ?point ref:hasTimeseriesId ?tsid .
  FILTER(?name IN ("Perimeter_top_ZN_3", "Perimeter_mid_ZN_3"))
}

SELECT ?name ?class WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?name .
  ?c a brick:AirTemperatureSensor .
  ?c brick:hasParent ?z .
} LIMIT 20

SELECT ?name WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?name .
} LIMIT 30

SELECT ?class WHERE {
  ?p a ?class .
  ?p ref:hasTimeseriesId ?ts .
  FILTER(?class = brick:AirTemperatureSensor)
} LIMIT 5

